def choose_chart(intent, n_categories):
    if intent == '构成':
        return '环形图' if n_categories <= 5 else '堆叠条形图'
    if intent == '趋势':
        return '折线图'
    if intent == '比较':
        return '排序后的横向条形图' if n_categories > 10 else '柱状图'
    if intent == '分布':
        return '直方图'
    if intent == '关系':
        return '散点图'
    return '无法判断'

cases = [('构成', 4), ('构成', 12), ('比较', 15), ('关系', 2)]
[choose_chart(i, n) for i, n in cases]

